use ruff_diagnostics::{AlwaysFixableViolation, Diagnostic, Edit, Fix};
use ruff_macros::{derive_message_formats, ViolationMetadata};
use ruff_python_ast::{self as ast, Expr, Stmt};
use ruff_python_semantic::{BindingKind, ScopeKind};
use ruff_python_trivia::{BackwardsTokenizer, SimpleTokenKind, SimpleTokenizer};
use ruff_text_size::{Ranged, TextRange};

use crate::checkers::ast::Checker;

/// ## What it does
/// Checks for `for` loops that can be replaced with `yield from` expressions.
///
/// ## Why is this bad?
/// If a `for` loop only contains a `yield` statement, it can be replaced with a
/// `yield from` expression, which is more concise and idiomatic.
///
/// ## Example
/// ```python
/// for x in foo:
///     yield x
/// ```
///
/// Use instead:
/// ```python
/// yield from foo
/// ```
///
/// ## Fix safety
/// This rule's fix is marked as unsafe, as converting a `for` loop to a `yield
/// from` expression can change the behavior of the program in rare cases.
/// For example, if a generator is being sent values via `send`, then rewriting
/// to a `yield from` could lead to an attribute error if the underlying
/// generator does not implement the `send` method.
///
/// In most cases, however, the fix is safe, and such a modification should have
/// no effect on the behavior of the program.
///
/// ## References
/// - [Python documentation: The `yield` statement](https://docs.python.org/3/reference/simple_stmts.html#the-yield-statement)
/// - [PEP 380 – Syntax for Delegating to a Subgenerator](https://peps.python.org/pep-0380/)
#[derive(ViolationMetadata)]
pub(crate) struct YieldInForLoop;

impl AlwaysFixableViolation for YieldInForLoop {
    #[derive_message_formats]
    fn message(&self) -> String {
        "Replace `yield` over `for` loop with `yield from`".to_string()
    }

    fn fix_title(&self) -> String {
        "Replace with `yield from`".to_string()
    }
}

/// UP028
pub(crate) fn yield_in_for_loop(checker: &mut Checker, stmt_for: &ast::StmtFor) {
    let ast::StmtFor {
        target,
        iter,
        body,
        orelse,
        is_async: _,
        range: _,
    } = stmt_for;

    let mut in_async_context = false;
    for scope in checker.semantic().current_scopes() {
        match scope.kind {
            ScopeKind::Function(function_def) => {
                in_async_context = function_def.is_async;
                break;
            }
            ScopeKind::Lambda(_) => {}
            ScopeKind::Class(_) => {}
            ScopeKind::Generator(_) => {}
            ScopeKind::Module | ScopeKind::Type => {}
        }
    }
    if in_async_context {
        return;
    }

    if !orelse.is_empty() {
        return;
    }

    let [body_stmt] = body.as_slice() else {
        return;
    };

    match body_stmt {
        Stmt::Assign(_) | Stmt::AnnAssign(_) | Stmt::AugAssign(_) => {
            return;
        }
        Stmt::Return(_) | Stmt::Raise(_) | Stmt::Delete(_) => {
            return;
        }
        Stmt::For(_) | Stmt::While(_) | Stmt::If(_) | Stmt::With(_) => {
            return;
        }
        Stmt::Pass(_) | Stmt::Break(_) | Stmt::Continue(_) | Stmt::Assert(_) => {
            return;
        }
        Stmt::Try(_) | Stmt::Match(_) | Stmt::Global(_) | Stmt::Nonlocal(_) => {
            return;
        }
        Stmt::Expr(ast::StmtExpr {
            value: body_value,
            range: _,
        }) => match body_value.as_ref() {
            Expr::Call(_) | Expr::BinOp(_) | Expr::UnaryOp(_) => {
                return;
            }
            Expr::Name(_) | Expr::Tuple(_) | Expr::List(_) | Expr::Attribute(_) => {
                return;
            }
            Expr::Await(_) | Expr::YieldFrom(_) | Expr::Compare(_) => {
                return;
            }
            Expr::BoolOp(_) | Expr::If(_) | Expr::Lambda(_) | Expr::Named(_) => {
                return;
            }
            Expr::Yield(ast::ExprYield {
                value: None,
                range: _,
            }) => {
                return;
            }
            Expr::Yield(ast::ExprYield {
                value: Some(yielded),
                range: _,
            }) => {
                let mut equivalent = true;
                let mut pending_pairs = vec![(target.as_ref(), yielded.as_ref())];
                while let Some((left, right)) = pending_pairs.pop() {
                    match (left, right) {
                        (Expr::Name(left_name), Expr::Name(right_name)) => {
                            if left_name.id != right_name.id {
                                equivalent = false;
                            }
                        }
                        (Expr::Tuple(left_tuple), Expr::Tuple(right_tuple)) => {
                            if left_tuple.len() == right_tuple.len() {
                                for (left_elt, right_elt) in
                                    left_tuple.iter().zip(right_tuple.iter())
                                {
                                    pending_pairs.push((left_elt, right_elt));
                                }
                            } else {
                                equivalent = false;
                            }
                        }
                        (Expr::List(_), Expr::List(_))
                        | (Expr::Starred(_), Expr::Starred(_))
                        | (Expr::Attribute(_), Expr::Attribute(_)) => {
                            equivalent = false;
                        }
                        (Expr::Subscript(_), Expr::Subscript(_))
                        | (Expr::Name(_), Expr::Tuple(_))
                        | (Expr::Tuple(_), Expr::Name(_)) => {
                            equivalent = false;
                        }
                        (Expr::Call(_), Expr::Call(_))
                        | (Expr::BinOp(_), Expr::BinOp(_))
                        | (Expr::UnaryOp(_), Expr::UnaryOp(_)) => {
                            equivalent = false;
                        }
                        _ => {
                            equivalent = false;
                        }
                    }
                    if !equivalent {
                        break;
                    }
                }

                if equivalent {
                    let mut yielded_names = Vec::new();
                    let mut pending_exprs = vec![yielded.as_ref()];
                    while let Some(expr) = pending_exprs.pop() {
                        match expr {
                            Expr::Name(name) => {
                                yielded_names.push(name);
                            }
                            Expr::Tuple(tuple) => {
                                for element in tuple.iter() {
                                    pending_exprs.push(element);
                                }
                            }
                            _ => {}
                        }
                    }

                    let mut referenced_outside = false;
                    for name in yielded_names {
                        if referenced_outside {
                            break;
                        }
                        let binding_ids: Vec<_> = checker
                            .semantic()
                            .current_scope()
                            .get_all(name.id.as_str())
                            .collect();
                        let mut found_bound = false;
                        for binding_id in binding_ids {
                            if found_bound {
                                break;
                            }
                            let binding = checker.semantic().binding(binding_id);
                            match &binding.kind {
                                BindingKind::Annotation
                                | BindingKind::Deletion
                                | BindingKind::UnboundException(_) => {}
                                BindingKind::LoopVar
                                | BindingKind::Assignment
                                | BindingKind::NamedExprAssignment
                                | BindingKind::Argument => {
                                    found_bound = true;
                                    for reference_id in &binding.references {
                                        let reference = checker.semantic().reference(*reference_id);
                                        referenced_outside |= reference.range() != name.range();
                                    }
                                }
                                BindingKind::BoundException
                                | BindingKind::WithItemVar
                                | BindingKind::FunctionDefinition(_)
                                | BindingKind::ClassDefinition(_) => {
                                    found_bound = true;
                                    for reference_id in &binding.references {
                                        let reference = checker.semantic().reference(*reference_id);
                                        referenced_outside |= reference.range() != name.range();
                                    }
                                }
                                BindingKind::Import(_)
                                | BindingKind::FromImport(_)
                                | BindingKind::SubmoduleImport(_)
                                | BindingKind::FutureImport => {
                                    found_bound = true;
                                    for reference_id in &binding.references {
                                        let reference = checker.semantic().reference(*reference_id);
                                        referenced_outside |= reference.range() != name.range();
                                    }
                                }
                                BindingKind::Global(_)
                                | BindingKind::Nonlocal(_, _)
                                | BindingKind::Builtin
                                | BindingKind::TypeParam
                                | BindingKind::Export(_)
                                | BindingKind::ConditionalDeletion(_) => {
                                    found_bound = true;
                                    for reference_id in &binding.references {
                                        let reference = checker.semantic().reference(*reference_id);
                                        referenced_outside |= reference.range() != name.range();
                                    }
                                }
                            }
                        }
                    }

                    if !referenced_outside {
                        let source = checker.locator().contents();
                        let comment_ranges = checker.comment_ranges();
                        let mut enclosing_parentheses = None;
                        let mut right_tokens = SimpleTokenizer::new(
                            source,
                            TextRange::new(iter.end(), stmt_for.end()),
                        );
                        let mut left_tokens =
                            BackwardsTokenizer::up_to(iter.start(), source, comment_ranges);
                        let mut keep_searching = true;
                        while keep_searching {
                            let Some(right) = right_tokens.next() else {
                                break;
                            };
                            match right.kind {
                                SimpleTokenKind::Whitespace
                                | SimpleTokenKind::Newline
                                | SimpleTokenKind::Comment
                                | SimpleTokenKind::Continuation => {}
                                SimpleTokenKind::RParen => {
                                    let mut found_open = false;
                                    while keep_searching {
                                        let Some(left) = left_tokens.next() else {
                                            keep_searching = false;
                                            break;
                                        };
                                        match left.kind {
                                            SimpleTokenKind::Whitespace
                                            | SimpleTokenKind::Newline
                                            | SimpleTokenKind::Comment
                                            | SimpleTokenKind::Continuation => {}
                                            SimpleTokenKind::LParen => {
                                                enclosing_parentheses =
                                                    Some(TextRange::new(left.start(), right.end()));
                                                found_open = true;
                                                break;
                                            }
                                            SimpleTokenKind::LBracket
                                            | SimpleTokenKind::LBrace
                                            | SimpleTokenKind::Comma
                                            | SimpleTokenKind::Colon => {
                                                keep_searching = false;
                                            }
                                            _ => {
                                                keep_searching = false;
                                            }
                                        }
                                    }
                                    if !found_open {
                                        keep_searching = false;
                                    }
                                }
                                SimpleTokenKind::RBracket
                                | SimpleTokenKind::RBrace
                                | SimpleTokenKind::Colon
                                | SimpleTokenKind::Comma => {
                                    keep_searching = false;
                                }
                                _ => {
                                    keep_searching = false;
                                }
                            }
                        }

                        let slice_range = enclosing_parentheses.unwrap_or_else(|| iter.range());
                        let iter_source = checker.locator().slice(slice_range);
                        let contents = format!("yield from {iter_source}");
                        let mut diagnostic = Diagnostic::new(YieldInForLoop, stmt_for.range());
                        diagnostic.set_fix(Fix::unsafe_edit(Edit::range_replacement(
                            contents,
                            stmt_for.range(),
                        )));
                        checker.diagnostics.push(diagnostic);
                    }
                }
            }
            _ => {
                return;
            }
        },
        _ => {
            return;
        }
    }
}

